def _qualified_target(suite: Suite) -> tuple[str, dict[str, str | None]]:
    target = suite.target or {}
    parts = {
        "catalog": target.get("catalog"),
        "schema": target.get("schema"),
        "table": target.get("table"),
    }
    if not parts["table"]:
        raise LLMOutputInvalidError(  # surfaced as a failed invocation, not a 500
            "the suite has no table target to generate SQL against"
        )
    qualified = ".".join(p for p in (parts["catalog"], parts["schema"], parts["table"]) if p)
